/// All rosary prayer texts in English, Latin, and Spanish
class RosaryPrayers {
  // Sign of the Cross
  static const signOfTheCross = {
    'en': 'In the name of the Father, and of the Son, and of the Holy Spirit. Amen.',
    'la': 'In nómine Patris, et Fílii, et Spíritus Sancti. Amen.',
    'es': 'En el nombre del Padre, y del Hijo, y del Espíritu Santo. Amén.',
  };

  // Apostles' Creed
  static const apostlesCreed = {
    'en': '''I believe in God, the Father Almighty, Creator of heaven and earth; and in Jesus Christ, His only Son, our Lord; Who was conceived by the Holy Spirit, born of the Virgin Mary; suffered under Pontius Pilate, was crucified, died, and was buried. He descended into hell; the third day He rose again from the dead. He ascended into heaven, and sits at the right hand of God, the Father Almighty; from thence He shall come to judge the living and the dead. I believe in the Holy Spirit, the Holy Catholic Church, the communion of Saints, the forgiveness of sins, the resurrection of the body, and life everlasting. Amen.''',
    'la': '''Credo in Deum Patrem omnipoténtem, Creatórem cæli et terræ. Et in Iesum Christum, Fílium eius únicum, Dóminum nostrum, qui concéptus est de Spíritu Sancto, natus ex María Vírgine, passus sub Póntio Piláto, crucifíxus, mórtuus, et sepúltus, descéndit ad ínferos, tértia die resurréxit a mórtuis, ascéndit ad cælos, sedet ad déxteram Dei Patris omnipoténtis, inde ventúrus est iudicáre vivos et mórtuos. Credo in Spíritum Sanctum, sanctam Ecclésiam cathólicam, sanctórum communiónem, remissiónem peccatórum, carnis resurrectiónem, vitam ætérnam. Amen.''',
    'es': '''Creo en Dios, Padre todopoderoso, Creador del cielo y de la tierra. Creo en Jesucristo, su único Hijo, nuestro Señor, que fue concebido por obra y gracia del Espíritu Santo, nació de Santa María Virgen, padeció bajo el poder de Poncio Pilato, fue crucificado, muerto y sepultado, descendió a los infiernos, al tercer día resucitó de entre los muertos, subió a los cielos y está sentado a la derecha de Dios, Padre todopoderoso. Desde allí ha de venir a juzgar a vivos y muertos. Creo en el Espíritu Santo, la santa Iglesia católica, la comunión de los santos, el perdón de los pecados, la resurrección de la carne y la vida eterna. Amén.''',
  };

  // Our Father
  static const ourFather = {
    'en': '''Our Father, who art in heaven, hallowed be Thy name; Thy kingdom come; Thy will be done on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses as we forgive those who trespass against us; and lead us not into temptation, but deliver us from evil. Amen.''',
    'la': '''Pater noster, qui es in cælis, sanctificétur nomen tuum. Advéniat regnum tuum. Fiat volúntas tua, sicut in cælo et in terra. Panem nostrum cotidiánum da nobis hódie. Et dimítte nobis débita nostra, sicut et nos dimíttimus debitóribus nostris. Et ne nos indúcas in tentatiónem, sed líbera nos a malo. Amen.''',
    'es': '''Padre nuestro, que estás en el cielo, santificado sea tu Nombre; venga a nosotros tu reino; hágase tu voluntad en la tierra como en el cielo. Danos hoy nuestro pan de cada día; perdona nuestras ofensas, como también nosotros perdonamos a los que nos ofenden; no nos dejes caer en la tentación, y líbranos del mal. Amén.''',
  };

  // Hail Mary
  static const hailMary = {
    'en': '''Hail Mary, full of grace, the Lord is with thee; blessed art thou among women, and blessed is the fruit of thy womb, Jesus. Holy Mary, Mother of God, pray for us sinners, now and at the hour of our death. Amen.''',
    'la': '''Ave María, grátia plena, Dóminus tecum. Benedícta tu in muliéribus, et benedíctus fructus ventris tui, Iesus. Sancta María, Mater Dei, ora pro nobis peccatóribus, nunc et in hora mortis nostræ. Amen.''',
    'es': '''Dios te salve, María, llena eres de gracia, el Señor es contigo; bendita tú eres entre todas las mujeres, y bendito es el fruto de tu vientre, Jesús. Santa María, Madre de Dios, ruega por nosotros pecadores, ahora y en la hora de nuestra muerte. Amén.''',
  };

  // Glory Be
  static const gloryBe = {
    'en': 'Glory be to the Father, and to the Son, and to the Holy Spirit. As it was in the beginning, is now, and ever shall be, world without end. Amen.',
    'la': 'Gloria Patri, et Fílio, et Spirítui Sancto. Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.',
    'es': 'Gloria al Padre, y al Hijo, y al Espíritu Santo. Como era en el principio, ahora y siempre, y por los siglos de los siglos. Amén.',
  };

  // Fatima Prayer (O My Jesus)
  static const fatimaPrayer = {
    'en': 'O my Jesus, forgive us our sins, save us from the fires of hell; lead all souls to heaven, especially those in most need of Thy mercy.',
    'la': 'O Iesu mi, dimítte nobis delícta nostra, líbera nos ab igne ínferni, concéde omnes ánimas in cælum addúcere, maxime illas quæ máxime indígent misericórdia tua.',
    'es': 'Oh Jesús mío, perdona nuestros pecados, líbranos del fuego del infierno, lleva al cielo a todas las almas, especialmente a las más necesitadas de tu misericordia.',
  };

  // Hail Holy Queen
  static const hailHolyQueen = {
    'en': '''Hail, holy Queen, Mother of mercy, hail, our life, our sweetness, and our hope. To thee do we cry, poor banished children of Eve; to thee do we send up our sighs, mourning and weeping in this valley of tears. Turn then, most gracious Advocate, thine eyes of mercy toward us; and after this our exile, show unto us the blessed fruit of thy womb, Jesus. O clement, O loving, O sweet Virgin Mary.

Pray for us, O holy Mother of God, that we may be made worthy of the promises of Christ.''',
    'la': '''Salve, Regína, Mater misericórdiæ; vita, dulcédo et spes nostra, salve. Ad te clamámus, éxsules fílii Hevæ; ad te suspirámus, geméntes et flentes in hac lacrimárum valle. Eia ergo, Advocáta nostra, illos tuos misericórdes óculos ad nos convérte. Et Iesum, benedíctum fructum ventris tui, nobis post hoc exsílium osténde. O clemens, O pia, O dulcis Virgo María.

Ora pro nobis, sancta Dei Génitrix, ut digni efficiámur promissiónibus Christi.''',
    'es': '''Dios te salve, Reina y Madre de misericordia, vida, dulzura y esperanza nuestra. Dios te salve. A ti clamamos los desterrados hijos de Eva; a ti suspiramos gimiendo y llorando en este valle de lágrimas. Ea, pues, Señora, abogada nuestra, vuelve a nosotros tus ojos misericordiosos, y después de este destierro muéstranos a Jesús, fruto bendito de tu vientre. ¡Oh clemente, oh piadosa, oh dulce Virgen María!

Ruega por nosotros, santa Madre de Dios, para que seamos dignos de alcanzar las promesas de nuestro Señor Jesucristo.''',
  };

  // Rosary Concluding Prayer
  static const concludingPrayer = {
    'en': '''O God, whose only-begotten Son, by His life, death, and resurrection, has purchased for us the rewards of eternal life; grant, we beseech Thee, that, meditating upon these mysteries of the Most Holy Rosary of the Blessed Virgin Mary, we may imitate what they contain and obtain what they promise, through the same Christ our Lord. Amen.''',
    'la': '''Deus, cuius Fílius únicus, vita, morte et resurrectióne sua, nos ætérnæ vitæ præmia consecúti est; concéde, quæsumus, ut hæc sacratíssimi Rosárii Beátæ Maríæ Vírginis mystéria pie recoléntes, et imitémur quod continént, et assequámur quod promíttunt. Per eúndem Christum Dóminum nostrum. Amen.''',
    'es': '''Oh Dios, cuyo Unigénito Hijo, con su vida, muerte y resurrección, nos ha merecido el premio de la vida eterna; concédenos, te rogamos, que meditando los misterios del santísimo Rosario de la Bienaventurada Virgen María, imitemos lo que contienen y alcancemos lo que prometen. Por el mismo Cristo nuestro Señor. Amén.''',
  };

  // Rosary for the Dead - De Profundis (Psalm 130)
  static const deProfundis = {
    'en': '''Out of the depths I cry to thee, O Lord! Lord, hear my voice! Let thy ears be attentive to the voice of my supplications! If thou, O Lord, shouldst mark iniquities, Lord, who could stand? But there is forgiveness with thee, that thou mayest be feared. I wait for the Lord, my soul waits, and in his word I hope; my soul waits for the Lord more than watchmen for the morning, more than watchmen for the morning. O Israel, hope in the Lord! For with the Lord there is steadfast love, and with him is plenteous redemption. And he will redeem Israel from all his iniquities.

Eternal rest grant unto them, O Lord, and let perpetual light shine upon them. May they rest in peace. Amen.''',
    'la': '''De profúndis clamávi ad te, Dómine; Dómine, exáudi vocem meam. Fiant aures tuæ intendéntes in vocem deprecatiónis meæ. Si iniquitátes observáveris, Dómine, Dómine, quis sustinébit? Quia apud te propitiátio est, et propter legem tuam sustínui te, Dómine. Sustínuit ánima mea in verbo eius; sperávit ánima mea in Dómino. A custódia matutína usque ad noctem, speret Israël in Dómino. Quia apud Dóminum misericórdia, et copiósa apud eum redémptio. Et ipse rédimet Israël ex ómnibus iniquitátibus eius.

Réquiem ætérnam dona eis, Dómine, et lux perpétua lúceat eis. Requiéscant in pace. Amen.''',
    'es': '''Desde lo profundo te invoco, Señor; Señor, escucha mi voz. Estén tus oídos atentos a la voz de mi súplica. Si llevas cuenta de los delitos, Señor, ¿quién podría resistir? Pero en ti se encuentra el perdón, por eso te respetamos. Mi alma aguarda al Señor, mi alma espera en su palabra. Desde la vigilia matutina hasta la noche, espere Israel al Señor. Porque en el Señor hay misericordia y copiosa redención. Él redimirá a Israel de todos sus delitos.

Dales, Señor, el descanso eterno, y brille para ellos la luz perpetua. Descansen en paz. Amén.''',
  };

  // Eternal Rest prayer (for Rosary for the Dead)
  static const eternalRest = {
    'en': 'Eternal rest grant unto them, O Lord, and let perpetual light shine upon them. May they rest in peace. Amen.',
    'la': 'Réquiem ætérnam dona eis, Dómine, et lux perpétua lúceat eis. Requiéscant in pace. Amen.',
    'es': 'Dales, Señor, el descanso eterno, y brille para ellos la luz perpetua. Descansen en paz. Amén.',
  };

  // Rosary for the Dead - final prayers
  static const deadRosaryClosing = {
    'en': '''May the souls of all the faithful departed, through the mercy of God, rest in peace. Amen.''',
    'la': '''Animæ ómnium fidélium defunctórum, per misericórdiam Dei, requiéscant in pace. Amen.''',
    'es': '''Las almas de todos los fieles difuntos, por la misericordia de Dios, descansen en paz. Amén.''',
  };

  // Get prayer by language
  static String get(String key, String lang) {
    switch (key) {
      case 'sign_of_the_cross': return signOfTheCross[lang] ?? signOfTheCross['en']!;
      case 'apostles_creed': return apostlesCreed[lang] ?? apostlesCreed['en']!;
      case 'our_father': return ourFather[lang] ?? ourFather['en']!;
      case 'hail_mary': return hailMary[lang] ?? hailMary['en']!;
      case 'glory_be': return gloryBe[lang] ?? gloryBe['en']!;
      case 'fatima_prayer': return fatimaPrayer[lang] ?? fatimaPrayer['en']!;
      case 'hail_holy_queen': return hailHolyQueen[lang] ?? hailHolyQueen['en']!;
      case 'concluding_prayer': return concludingPrayer[lang] ?? concludingPrayer['en']!;
      case 'de_profundis': return deProfundis[lang] ?? deProfundis['en']!;
      case 'eternal_rest': return eternalRest[lang] ?? eternalRest['en']!;
      case 'dead_rosary_closing': return deadRosaryClosing[lang] ?? deadRosaryClosing['en']!;
      default: return '';
    }
  }
}